const esc=value=>String(value||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderPublic(record,shell){
  if(record?.status!=='published'||!['journal','postcard'].includes(record.kind))return null;
  const canonical='https://dainyelonthemove.com/'+record.url;
  const description=record.subtitle||record.text.slice(0,155);
  const schema=JSON.stringify({'@context':'https://schema.org','@type':'BlogPosting',headline:record.title,url:canonical,datePublished:record.publishedAt,dateModified:record.updatedAt||record.publishedAt,author:{'@type':'Person',name:'Dainyel'}}).replace(/</g,'\\u003c');
  const image=record.photo?`<figure><img src="/${esc(record.photo.src)}" alt="${esc(record.photo.alt)}" width="640" height="420"/><figcaption>${esc(record.eventDate||record.sentDate)}</figcaption></figure>`:'';
  const paragraphs=record.kind==='journal'?[record.text]:record.paragraphs;
  const links=record.kind==='journal'?[record.storyUrl].filter(Boolean):record.storyUrls;
  const body=image+paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')+`<p>Published ${esc(record.publishedAt?.slice(0,10))}</p><nav class="journey-links">`+links.map(url=>`<a href="/${esc(url)}">Explore the related story →</a>`).join('')+`<a href="/${record.kind==='journal'?'field-notes':'postcards'}.html">Back to the archive →</a></nav>`;
  return `<!doctype html><html lang="en-GB"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>${esc(record.title)} | Dainyel on the Move</title><meta name="description" content="${esc(description)}"/><link rel="canonical" href="${canonical}"/><meta property="og:title" content="${esc(record.title)}"/><meta property="og:description" content="${esc(description)}"/><meta property="og:url" content="${canonical}"/><meta property="og:type" content="article"/><meta property="og:image" content="https://dainyelonthemove.com/${esc(record.photo?.src||'assets/optimized/hero-bay-1280.webp')}"/><meta name="twitter:card" content="summary_large_image"/><script type="application/ld+json">${schema}</script><link rel="stylesheet" href="/assets/design-system.css"/><link rel="stylesheet" href="/assets/journey-experience.css"/><script defer src="/assets/site-ui.js"></script></head><body class="public-page journey-page">${shell.header}<main id="main-content"><section class="overview-hero wrap"><span class="eyebrow">${record.kind==='journal'?'Field Notes':'Postcards'}</span><h1>${esc(record.title)}</h1></section><article class="wrap journal-detail">${body}</article></main>${shell.footer}</body></html>`;
}
